// 直近30日以内のチェックイン（未来の予約を含む）だけを DB の列に変換する
const JST = 9 * 3600 * 1000;
const cutoff = new Date(Date.now() + JST - 30 * 86400000).toISOString().slice(0, 10);

// シリアル値・文字列のどちらでも 'YYYY-MM-DD HH:MM:SS' に揃える
const toDateTime = v => {
  if (typeof v === 'number') {
    return new Date(Math.round((v - 25569) * 86400000)).toISOString().slice(0, 19).replace('T', ' ');
  }
  const m = String(v ?? '').match(/(\d{4})[-\/](\d{1,2})[-\/](\d{1,2})(?:\s+(\d{1,2}):(\d{2})(?::(\d{2}))?)?/);
  if (!m) return null;
  const p = n => String(n ?? 0).padStart(2, '0');
  return `${m[1]}-${p(m[2])}-${p(m[3])} ${p(m[4])}:${p(m[5])}:${p(m[6])}`;
};
const toDate = v => toDateTime(v)?.slice(0, 10) ?? null;
// シリアル値（1日未満の小数）・'15:30' 形式のどちらでも 'HH:MM:00' に揃える
const toTime = v => {
  if (typeof v === 'number') {
    const min = Math.round((v % 1) * 1440);
    return `${String(Math.floor(min / 60)).padStart(2, '0')}:${String(min % 60).padStart(2, '0')}:00`;
  }
  const m = String(v ?? '').match(/(\d{1,2}):(\d{2})/);
  return m ? `${m[1].padStart(2, '0')}:${m[2]}:00` : null;
};
const str = v => (v === '' || v == null) ? null : String(v).trim();

return $input.all().flatMap(({ json: r }) => {
  const submittedAt = toDateTime(r['タイムスタンプ']);
  const checkIn = toDate(r['チェックイン']);
  const fullName = str(r['氏名']);
  if (!submittedAt || !checkIn || !fullName || checkIn < cutoff) return [];
  return [{
    json: {
      row_key: `${submittedAt}|${fullName}`,
      submitted_at: submittedAt,
      check_in: checkIn,
      check_out: toDate(r['チェックアウト']),
      check_in_time: toTime(r['チェックイン予定時刻']),
      is_representative: r['代表者'] === '○' ? 1 : 0,
      representative_name: str(r['宿泊代表者氏名']),
      full_name: fullName,
      name_kana: str(r['フリガナ']),
      address: str(r['住所']),
      phone: str(r['電話番号']),
      email: str(r['メール']),
      has_jp_address: String(r['国内住所']).startsWith('はい') ? 1 : 0,
      nationality: str(r['国籍']),
      passport_no: str(r['旅券番号']),
    },
  }];
});
